    const nextCell=r=>{if(!r.next)return '<span class="muted">none</span>';const late=r.next<at;return `<span class="${late?'due late':'due'}">${late?'overdue '+E(friendly(r.next)):E(friendly(r.next))}</span>`;};
    const table=`<div class="table-scroll"><table class="people"><thead><tr><th>Person</th><th>Tier</th><th>We last reached out</th><th>They last came back</th><th>Next touch</th><th>Odds</th></tr></thead><tbody>${list.slice(0,app.peopleAll?500:60).map(r=>`<tr data-action="openRecord" data-id="${E(r.x.r.id)}" tabindex="0" role="button"><td><b>${E(r.x.r.name||r.x.r.company)}</b><br><small class="muted">${E(r.x.r.company||'')}</small></td><td>${E(r.tier)}</td><td>${ago(r.out)}</td><td>${ago(r.back)}</td><td>${nextCell(r)}</td><td>${r.x.m&&r.x.m.stage!=='closed'&&r.x.m.who!=='other'?E(pct(r.x.m.p)):''}</td></tr>`).join('')}</tbody></table></div>${list.length>60&&!app.peopleAll?`<div class="footer-row"><span class="tiny muted"></span>${btn(`Show all ${list.length}`,'peopleAll','','small ghost')}</div>`:''}`;
    const counts={Due:rows.filter(due).length,A:rows.filter(r=>r.tier==='A').length,B:rows.filter(r=>r.tier==='B').length,C:rows.filter(r=>r.tier==='C').length,All:rows.length};
    const open=openTasks().filter(t=>matchesOwner(t.owner)&&(!t.due||t.due<=D.addDays(at,14)));const by={};open.forEach(t=>{const k=taskKind(t);(by[k]=by[k]||[]).push(t);});
