  function renderEvents(){const today=D.today();let rows=data.plannedEvents.filter(e=>!e.archived);if(app.eventStatus==='Upcoming')rows=rows.filter(e=>e.date>=today&&!['Completed','Declined'].includes(e.status));if(app.eventStatus==='Qualified')rows=rows.filter(e=>['Qualified','Deciding'].includes(e.status));if(app.eventStatus==='Booked')rows=rows.filter(e=>['Booked','Attending'].includes(e.status));if(app.eventStatus==='Watch')rows=rows.filter(e=>e.status==='Watch');if(app.eventStatus==='Research')rows=rows.filter(e=>['Research','Interested','Deciding'].includes(e.status));if(app.eventStatus==='Past')rows=rows.filter(e=>e.date<today||e.status==='Completed');rows.sort((a,b)=>(a.date||'9999').localeCompare(b.date||'9999')||(a.title||'').localeCompare(b.title||''));const booked=rows.filter(e=>['Booked','Attending'].includes(e.status)).length;return heading('Events.','Turn attendance into planned conversations, clear ownership and recorded follow-up.',btn('Add event','addEvent','','primary','plus'))+`<div class="stats"><div class="stat"><strong>${rows.length}</strong><div class="label">${E(app.eventStatus)} events</div><small>Shared between Barry and Graeme</small></div><div class="stat"><strong>${booked}</strong><div class="label">Booked or attending</div><small>Confirmed decisions only</small></div><div class="stat"><strong>${rows.filter(e=>e.targets).length}</strong><div class="label">With target contacts</div><small>Named conversations improve value</small></div></div><div class="tabs" aria-label="Event status">${['Upcoming','Qualified','Booked','Watch','Research','Past'].map(s=>`<button data-action="eventStatus" data-status="${s}" class="${app.eventStatus===s?'active':''}">${s}</button>`).join('')}</div><section class="panel table-scroll"><table><thead><tr><th>Date</th><th>Event</th><th>Decision</th><th>Owner</th><th>Commercial purpose</th><th>Targets</th></tr></thead><tbody>${rows.map(e=>`<tr><td><b>${friendly(e.date)}</b>${e.time?`<small>${E(e.time)}</small>`:''}</td><td><button class="table-title" data-action="editEvent" data-id="${E(e.id)}"><b>${E(e.title)}</b><small>${E(e.location||e.organiser||'Location to confirm')}</small></button></td><td><span class="tag ${['Booked','Attending'].includes(e.status)?'success':e.status==='Deciding'?'attention':'plain'}">${E(e.status||'Research')}</span>${e.cost?`<small>${E(e.cost)}</small>`:''}</td><td>${E(e.owner||'Unassigned')}</td><td style="max-width:320px">${E(e.objective||'Define the commercial purpose before booking.')}</td><td style="max-width:260px">${E(e.targets||'No named targets yet')}</td></tr>`).join('')}</tbody></table>${rows.length?'':empty('No events in this view','Add an event or choose another status.')}</section>`;}
  function eventModal(id=''){const existing=data.plannedEvents.find(e=>e.id===id)||{id:'event:'+newId(),status:'Research',owner:app.actor,date:'',title:'',location:'',organiser:'',cost:'',link:'',fit:'',objective:'',targets:'',expectedOutcome:'',bookingDeadline:'',bookingReference:'',notes:'',archived:false,_rev:0};openModal({title:id?'Update event':'Add an event',deck:'Research can be recorded without implying a booking.',wide:true,body:`<div class="field-grid">${modalField('Event name','title',existing.title)}${modalField('Date','date',existing.date,'date')}${modalField('Time','time',existing.time||'')}${modalField('Location','location',existing.location||'')}${modalField('Organiser','organiser',existing.organiser||'')}${modalField('Owner','owner',existing.owner||app.actor,'text',['Barry','Graeme'])}${modalField('Status','status',existing.status||'Research','text',['Research','Interested','Qualified','Deciding','Booked','Attending','Watch','Completed','Declined'])}${modalField('Cost / ticket','cost',existing.cost||'')}${modalField('Event link','link',existing.link||'','url')}</div><div class="stack section-gap" style="gap:14px">${modalField('Why this fits Vanor','fit',existing.fit||'','textarea')}${modalField('Commercial purpose','objective',existing.objective||'','textarea')}${modalField('People or organisations to meet','targets',existing.targets||'','textarea')}${modalField('Minimum worthwhile outcome','expectedOutcome',existing.expectedOutcome||'','textarea')}${modalField('Booking deadline','bookingDeadline',existing.bookingDeadline||'','date')}${modalField('Booking reference / evidence','bookingReference',existing.bookingReference||'')}${modalField('Notes','notes',existing.notes||'','textarea')}</div>${id?`<div class="row section-gap">${btn('Archive event','archiveEvent',existing.id,'ghost danger')}</div>`:''}`,submit:id?'Save event':'Add event',onSubmit:async f=>{const p={...existing,...Object.fromEntries(f.entries()),updatedAt:new Date().toISOString()};if(!p.title||!D.validDate(p.date))throw new Error('Enter an event name and valid date.');const eventKey=v=>D.clean(v).toLowerCase().replace(/[^a-z0-9]+/g,' ').trim();const duplicate=data.plannedEvents.find(e=>e.id!==p.id&&!e.archived&&e.date===p.date&&eventKey(e.title)===eventKey(p.title));if(duplicate)throw new Error('This event already exists on '+friendly(duplicate.date)+'. Open the existing record instead.');if(['Qualified','Deciding','Booked','Attending'].includes(p.status)&&(!p.owner||!p.fit||!p.objective||!p.targets||!p.expectedOutcome))throw new Error('Qualification needs an owner, Vanor fit, commercial purpose, target contacts and a worthwhile outcome.');if(['Booked','Attending'].includes(p.status)&&!p.bookingReference)throw new Error('Record the booking confirmation or reference before marking this event booked.');const saved=await repo.savePlannedEvent(p,existing._rev||0,{type:id?'Event updated':'Event added',actor:app.actor,note:p.title+' / '+p.status});data.plannedEvents=id?data.plannedEvents.map(e=>e.id===id?saved:e):[...data.plannedEvents,saved];render();toast(id?'Event updated.':'Event added to the shared tracker.');}});}
  function renderLayers(){const holder=element.querySelector('[data-layers]');if(!holder)return;if(!holder.firstChild)holder.innerHTML='<div data-drawer-layer></div><div data-modal-layer></div><div data-toast-layer></div>';const dHtml='';const draw=holder.querySelector('[data-drawer-layer]');if(draw._html!==dHtml){draw.innerHTML=dHtml;draw._html=dHtml;}const mod=holder.querySelector('[data-modal-layer]');if(mod._html!==modalHtml){mod.innerHTML=modalHtml;mod._html=modalHtml;}const t=holder.querySelector('[data-toast-layer]');if(t._html!==toastHtml){t.innerHTML=toastHtml;t._html=toastHtml;}}
