  async function searchModal(){if(!await flush())return;openModal({title:'Find a relationship or pursuit',deck:'Search every retained record, not just the first page.',body:`<div class="command-search">${icon('search')}<input id="command-input" type="search" aria-label="Search the entire workspace" placeholder="Name, company, project or source ID..."></div><div class="command-results" id="command-results">${commandResults('')}</div>`,wide:true});setTimeout(()=>element.querySelector('#command-input')?.focus(),40);}
