      if(el.id==='segment-filter'){if(!await flush())return;app.segment=el.value;app.networkPage=0;app.selected='';render();return;}
      if(el.id==='region-filter'){if(!await flush())return;app.region=el.value;app.networkPage=0;app.prioPage=0;app.selected='';render();return;}
      if(el.id==='fit-filter'){if(!await flush())return;app.fit=el.value;app.networkPage=0;app.reviewPage=0;app.selected='';render();return;}
      if(el.id==='board-filter'){if(!await flush())return;app.boardFilter=el.value;render();return;}
